1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
13	
14	import java.time.LocalDate;
15	import java.util.Collection;
16	import java.util.List;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public abstract class OwnerMapper {
23	
24	    /**
25	     * More than this many owners already sharing a {@code registrationDate} raises the
26	     * {@code bulkSignupWarning} on responses for that day.
27	     */
28	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
29	
30	    /**
31	     * The hard per-city capacity limit: a city already holding this many owners rejects further
32	     * creates (see
33	     * {@link org.springframework.samples.petclinic.rest.function.owner.EnsureCityCapacity}).
34	     */
35	    private static final int CITY_CAPACITY_LIMIT = 50;
36	
37	    /**
38	     * A city already holding at least this many (but fewer than {@link #CITY_CAPACITY_LIMIT})
39	     * owners raises the {@code capacityWarning} on responses, signalling it is approaching the limit.
40	     */
41	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
42	
43	    @Autowired
44	    protected OwnerRepository ownerRepository;
45	
46	    @Mapping(target = "displayName",
47	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
48	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
49	    @Mapping(target = "initials",
50	            expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
51	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
52	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
53	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
54	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
55	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
56	    @Mapping(target = "locality", expression = "java(locality(owner))")
57	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
58	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
59	    @Mapping(target = "capacityWarning", expression = "java(capacityWarning(owner))")
60	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
61	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
62	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
63	    @Mapping(target = "identityKey",
64	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(owner))")
65	    @Mapping(target = "telephoneDisplay",
66	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.Telephones.toDisplay(owner.getTelephone()))")
67	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
68	    public abstract OwnerDto toOwnerDto(Owner owner);
69	
70	    /**
71	     * The canonical API path to this owner: {@code /api/owners/} followed by the owner's id.
72	     * Returns {@code null} when the owner has no id (e.g. before it has been persisted).
73	     */
74	    protected String selfLink(Owner owner) {
75	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
76	    }
77	
78	    /**
79	     * The owner's {@code membershipPoints}: the raw loyalty score (see
80	     * {@link org.springframework.samples.petclinic.rest.function.owner.Memberships}), built from a
81	     * present email, no namesakes, a household of 3 or more and tenure over one elapsed fiscal year.
82	     */
83	    protected int membershipPoints(Owner owner) {
84	        long householdSize = org.springframework.samples.petclinic.rest.function.owner.Households
85	                .size(owner, ownerRepository);
86	        return org.springframework.samples.petclinic.rest.function.owner.Memberships
87	                .membershipPoints(owner, householdSize);
88	    }
89	
90	    /**
91	     * The owner's {@code membershipLevel}: the grade {@code membershipPoints} buckets into — 1 for
92	     * 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more — after the household level ceiling, which
93	     * caps a member at one above the current maximum level among the household members that already
94	     * existed when it joined (see
95	     * {@link org.springframework.samples.petclinic.rest.function.owner.Memberships#cappedLevel}).
96	     */
97	    protected int membershipLevel(Owner owner) {
98	        return org.springframework.samples.petclinic.rest.function.owner.Memberships
99	                .cappedLevel(owner, ownerRepository);
100	    }
101	
102	    /**
103	     * The owner's preferred contact channel: {@code EMAIL} when an email address is
104	     * present (non-null and non-blank), otherwise {@code PHONE}.
105	     */
106	    protected OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
107	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
108	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
109	    }
110	
111	    /** The age (in years) at which an owner stops being a minor and becomes an adult. */
112	    private static final int ADULT_AGE = 18;
113	
114	    /** The age (in years) at which an owner becomes a senior. */
115	    private static final int SENIOR_AGE = 65;
116	
117	    /**
118	     * Derives the owner's {@code ageBand} from {@code birthDate} as of the
119	     * {@code registrationDate}: {@code MINOR} when under {@value #ADULT_AGE},
120	     * {@code ADULT} when {@value #ADULT_AGE} to {@value #SENIOR_AGE}-1, and
121	     * {@code SENIOR} when {@value #SENIOR_AGE} or older. Returns {@code null} when
122	     * either the birth date or the registration date is absent, so an owner created
123	     * without a birth date has no age band.
124	     */
125	    protected OwnerDto.AgeBandEnum ageBand(Owner owner) {
126	        LocalDate birthDate = owner.getBirthDate();
127	        LocalDate registrationDate = owner.getRegistrationDate();
128	        if (birthDate == null || registrationDate == null) {
129	            return null;
130	        }
131	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
132	        if (age < ADULT_AGE) {
133	            return OwnerDto.AgeBandEnum.MINOR;
134	        }
135	        if (age < SENIOR_AGE) {
136	            return OwnerDto.AgeBandEnum.ADULT;
137	        }
138	        return OwnerDto.AgeBandEnum.SENIOR;
139	    }
140	
141	    /**
142	     * Derives the owner's {@code locality} (canonical region string) from the
143	     * region-and-hash identity: the REGION segment of the {@code customerCode} (everything
144	     * before the first {@code '-'}). Legacy owners with no customer code (e.g. seed data)
145	     * fall back to deriving the region directly from postcode, then city, then
146	     * {@code "UNKNOWN"}.
147	     */
148	    protected String locality(Owner owner) {
149	        String region = org.springframework.samples.petclinic.rest.function.owner.CustomerCodes
150	                .regionOf(owner.getCustomerCode());
151	        if (region != null) {
152	            return region;
153	        }
154	        return org.springframework.samples.petclinic.rest.function.owner.CustomerCodes.region(owner);
155	    }
156	
157	    /** The lowest {@code membershipLevel} that grades an owner's segment TIER as {@code PREMIUM}. */
158	    private static final int PREMIUM_MIN_LEVEL = 3;
159	
160	    /**
161	     * The owner's {@code ownerSegment} formatted '&lt;TIER&gt;_&lt;AREA&gt;'. TIER is
162	     * {@code PREMIUM} when {@link #membershipLevel(Owner) membershipLevel} is
163	     * {@value #PREMIUM_MIN_LEVEL} or more, otherwise {@code STANDARD}. AREA is {@code METRO} when
164	     * the {@link #locality(Owner) locality} is a known region (NSW, VIC or QLD), otherwise
165	     * {@code REGIONAL}.
166	     */
167	    protected OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
168	        String tier = membershipLevel(owner) >= PREMIUM_MIN_LEVEL ? "PREMIUM" : "STANDARD";
169	        String area = REGION_TIMEZONE.containsKey(locality(owner)) ? "METRO" : "REGIONAL";
170	        return OwnerDto.OwnerSegmentEnum.fromValue(tier + "_" + area);
171	    }
172	
173	    /** Fixed region -> IANA timezone table. */
174	    private static final java.util.Map<String, String> REGION_TIMEZONE = java.util.Map.of(
175	            "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
176	
177	    /**
178	     * Derives the owner's {@code timezone} (IANA name) from the {@link #locality(Owner)
179	     * locality}/region via the fixed region-to-timezone table (NSW->Australia/Sydney,
180	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane). Returns {@code null} when the
181	     * region is not in the table (e.g. an {@code UNKNOWN} locality), so such owners have
182	     * no timezone.
183	     */
184	    protected String timezone(Owner owner) {
185	        return REGION_TIMEZONE.get(locality(owner));
186	    }
187	
188	    /**
189	     * The owner's {@code fiscalYear}: the {@code FY<YY>} label for the fiscal year (starting 1 July)
190	     * containing the business-day-adjusted {@code registrationDate} (e.g. 'FY27'). Returns
191	     * {@code null} when the registration date is absent (e.g. legacy seed owners).
192	     */
193	    protected String fiscalYear(Owner owner) {
194	        LocalDate registrationDate = owner.getRegistrationDate();
195	        if (registrationDate == null) {
196	            return null;
197	        }
198	        return org.springframework.samples.petclinic.rest.function.owner.FiscalYears.label(registrationDate);
199	    }
200	
201	    /**
202	     * Builds the membership number '<customerCode>-M<YY>', where YY is the last two digits of the
203	     * fiscal year (starting 1 July) containing the registrationDate (e.g. 'NSW-1A2B3C4D-M27').
204	     * Returns {@code null} when either the customer code or the registration date is absent (e.g.
205	     * legacy seed owners).
206	     */
207	    protected String membershipNumber(Owner owner) {
208	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
209	            return null;
210	        }
211	        int fiscalYear = org.springframework.samples.petclinic.rest.function.owner.FiscalYears
212	                .of(owner.getRegistrationDate());
213	        return String.format("%s-M%02d", owner.getCustomerCode(), fiscalYear % 100);
214	    }
215	
216	    /**
217	     * True when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} other owners have already
218	     * been created for this owner's {@code registrationDate}, using the same per-day
219	     * accumulation the daily create limit enforces (the owner itself is excluded). Returns
220	     * {@code false} when the owner has no registration date (e.g. legacy seed owners).
221	     */
222	    protected boolean bulkSignupWarning(Owner owner) {
223	        LocalDate registrationDate = owner.getRegistrationDate();
224	        if (registrationDate == null) {
225	            return false;
226	        }
227	        long count = ownerRepository.findAll().stream()
228	                .filter(existing -> !existing.getId().equals(owner.getId()))
229	                .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
230	                .count();
231	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
232	    }
233	
234	    /**
235	     * True when the owner's city already holds between {@value #CITY_CAPACITY_WARNING_THRESHOLD}
236	     * and {@code CITY_CAPACITY_LIMIT - 1} owners (the owner itself excluded), signalling the city
237	     * is approaching the hard capacity limit of {@value #CITY_CAPACITY_LIMIT}; otherwise false. The
238	     * city is compared case-insensitively with runs of whitespace collapsed to a single space,
239	     * mirroring {@link org.springframework.samples.petclinic.rest.function.owner.EnsureCityCapacity}.
240	     */
241	    protected boolean capacityWarning(Owner owner) {
242	        String city = normalizeCity(owner.getCity());
243	        long count = ownerRepository.findAll().stream()
244	                .filter(existing -> !existing.getId().equals(owner.getId()))
245	                .filter(existing -> normalizeCity(existing.getCity()).equals(city))
246	                .count();
247	        return count >= CITY_CAPACITY_WARNING_THRESHOLD && count < CITY_CAPACITY_LIMIT;
248	    }
249	
250	    private static String normalizeCity(String value) {
251	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
252	    }
253	
254	    /**
255	     * The Luhn check digit (0-9) computed over the digits contained in the owner's
256	     * {@code customerCode}. Returns {@code null} when the customer code is absent (e.g.
257	     * legacy seed owners).
258	     */
259	    protected Integer checkDigit(Owner owner) {
260	        String customerCode = owner.getCustomerCode();
261	        if (customerCode == null) {
262	            return null;
263	        }
264	        int sum = 0;
265	        boolean dbl = true;
266	        for (int i = customerCode.length() - 1; i >= 0; i--) {
267	            char c = customerCode.charAt(i);
268	            if (c < '0' || c > '9') {
269	                continue;
270	            }
271	            int d = c - '0';
272	            if (dbl) {
273	                d *= 2;
274	                if (d > 9) {
275	                    d -= 9;
276	                }
277	            }
278	            sum += d;
279	            dbl = !dbl;
280	        }
281	        return (10 - (sum % 10)) % 10;
282	    }
283	
284	    /**
285	     * The owner's {@code salutation}: the {@code title} followed by a single space and the last
286	     * name when a title is supplied (non-null and non-blank), otherwise just the last name.
287	     */
288	    protected String salutation(Owner owner) {
289	        String title = owner.getTitle();
290	        if (title == null || title.isBlank()) {
291	            return owner.getLastName();
292	        }
293	        return title + " " + owner.getLastName();
294	    }
295	
296	    public abstract Owner toOwner(OwnerDto ownerDto);
297	
298	    @Mapping(target = "id", ignore = true)
299	    @Mapping(target = "pets", ignore = true)
300	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
301	
302	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
303	
304	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
305	
306	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
307	        OwnerPageDto ownerPageDto = new OwnerPageDto();
308	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
309	        ownerPageDto.setPage(ownerPage.getNumber());
310	        ownerPageDto.setSize(ownerPage.getSize());
311	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
312	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
313	        return ownerPageDto;
314	    }
315	}
